{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.00) and model overestimates prices.",
    "Reduce forecast peaks by 5-15% after sharp upward spikes (e.g., >10% from prior day) to avoid overshoot.",
    "Apply mean reversion bias: if 3 consecutive days show model overestimating, reduce forecast by 2-5% per day.",
    "Increase forecast sensitivity to recent low prices (last 5 days) when sentiment is neutral or positive (sentiment > 0.00).",
    "For long-term (30-day) forecasts, cap upward revisions at +10% above recent 15-day average to prevent overconfidence.",
    "When sentiment turns positive (≥ 0.25), shift forecast toward historical mean of last 15 days, not recent highs."
  ]
}
